-- Update: johnny-furphy practice_limited 2026-10-30
INSERT INTO progress_updates (injury_id, update_date, stage, status_label, notes, source)
SELECT i.id, '2026-10-30', 'practice_limited', 'Practicing with G League Boom', 'Pacers assigned him to the G League''s Noblesville Boom so he could get practice time as he rehabs; recalled Oct 31. Still no firm return date.', 'https://www.rotowire.com/basketball/headlines/johnny-furphy-injury-practicing-in-g-league-536814'
FROM injuries i JOIN players p ON p.id = i.player_id
WHERE p.slug = 'johnny-furphy' AND p.league = 'NBA' AND i.injury_type = 'ACL' AND i.injury_date = '2026-02-08'
  AND NOT EXISTS (SELECT 1 FROM progress_updates x WHERE x.injury_id = i.id AND x.stage = 'practice_limited' AND x.update_date = '2026-10-30');

